// app/components/NewHeader.tsx
import React from "react";
import styles from '../styles/NewHeader.module.css'; // Estilos del encabezado

interface NewHeaderProps {
  setShowCartResume: (state: boolean) => void;
  itemQuantity: number; // Agregamos la propiedad itemQuantity
}

const NewHeader: React.FC<NewHeaderProps> = ({ setShowCartResume, itemQuantity }) => {
  return (
    <header className={styles.header}>
      <h1 className={styles.title}>Tienda Online</h1>
      <button onClick={() => setShowCartResume(true)} className={styles.cartButton}>
        Ver carrito ({itemQuantity})
      </button>
    </header>
  );
};

export default NewHeader;
