import React from 'react';
import { useCart } from '../context/CartContext'; // Importa el contexto de carrito
import { Products } from '../Data/Products';
import styles from '../styles/NewProductsContainer.module.css';

const NewProductsContainer: React.FC = () => {
  const { cart, addProduct } = useCart(); // Usa el contexto para acceder al carrito

  return (
    <div className={styles.container}>
      <h2 className={styles.heading}>Productos Disponibles</h2>
      <div className={styles.products}>
        {Products.map((product) => (
          <div key={product.code} className={styles.product}>
            <img src={product.srcImage} alt={product.title} className={styles.productImage} />
            <h3>{product.title}</h3>
            <p>${product.price}</p>
            <button
              onClick={() => addProduct(product.code)} // Llama a la función para agregar el producto
              className={styles.addToCartButton}
            >
              Agregar al carrito
            </button>
          </div>
        ))}
      </div>
      <div className={styles.cartInfo}>
        <p>Productos en el carrito: {cart.length}</p>
      </div>
    </div>
  );
};

export default NewProductsContainer;
